b = np.random.randn(3072)      # bias term added to every output row

Y = X @ W + b  # matrix multiply then broadcast-add bias
print(f"Input  X: {X.shape}")   # (4, 768)
print(f"Weight W: {W.shape}")   # (768, 3072)
print(f"Bias   b: {b.shape}")   # (3072,)
