def main() -> int:
    fixed = 0
    for rel, cap_num, block in BLOCKS:
        p = ROOT / rel
        if not p.exists():
            print(f'  MISSING file: {rel}')
            continue
        text = p.read_text(encoding='utf-8')
        anc = anchor(cap_num)
        if anc not in text:
            print(f'  NO ANCHOR for {cap_num} in {rel}')
            continue
        # Idempotent: check if the unique first line of the block is already present
        signature = block.split('\n')[1][:50]
        if signature and signature in text:
            print(f'  already inserted: {cap_num}')
            continue
        new_text = text.replace(anc, block + anc, 1)
        p.write_text(new_text, encoding='utf-8')
        print(f'  + {cap_num} in {rel}')
        fixed += 1
    print(f'\nInserted {fixed} appendix code blocks.')
    return 0


if __name__ == '__main__':
    sys.exit(main())
